url='/posts/'+public
check(post('Owner','/create_post',content='PRIVATE CIRCLE SENTINEL',circle_id=pc).status_code==302,'Missing choice defaults members-only')
private_pid=query('SELECT MAX(post_id) FROM circle_posts WHERE circle_id=?',(pc,))[0][0]
with app.app_context():private_public=public_ids.public(core.get_db(),'post',private_pid)
change('INSERT INTO comments(post_id,user_id,content,created_at) VALUES (?,?,?,CURRENT_TIMESTAMP)',(pid,users['Owner'],'MEMBER REPLY SENTINEL'))
guest=app.test_client()
for client in (guest,clients['Outsider']):
 r=client.get('/circles/'+pt)
 check(r.status_code==200 and b'PUBLIC CIRCLE SENTINEL' in r.data,'Nonmember reads public Circle feed')
 check(b'PRIVATE CIRCLE SENTINEL' not in r.data and b'MEMBER REPLY SENTINEL' not in r.data,'Private post and replies absent in public feed')
 check(b'CircleFixtureMember' not in r.data and b'Leave a comment' not in r.data,'No member directory or reply form disclosed')
 check(client.get(url).status_code==200,'Public original route readable')
 check(client.get('/posts/'+private_public).status_code==404,'Private original route remains denied')
 check(client.get(url+'/history').status_code==404,'Private previous edits cannot leak through history')
check(b'PRIVATE CIRCLE SENTINEL' in get('Owner','/circles/'+pt).data,'Member sees private and public posts')
check(b'MEMBER REPLY SENTINEL' in get('Owner',url).data,'Members retain replies')
check(post('Outsider','/create_comment',post_id=public,content='FORGED REPLY').status_code in (403,404),'Public readability never grants replying')
check(post('Outsider','/create_post',circle_id=pc,content='FORGED POST',circle_audience='public').status_code==404,'Public readability never grants posting')
check(post('Owner','/create_post',circle_id=hidden,content='FORGED PUBLIC',circle_audience='public').status_code==400,'Hidden Circle cannot accept public flag')
check(guest.get('/circles/'+hidden_opaque).status_code==404,'Hidden Circle stays hidden to visitors')
check(b'PUBLIC CIRCLE SENTINEL' in guest.get('/circles/'+pt+'?q=PUBLIC').data,'Public search returns eligible posts')
check(b'PRIVATE CIRCLE SENTINEL' not in guest.get('/circles/'+pt+'?q=PRIVATE').data,'Private search produces no private matches')
check(pt.encode() in guest.get('/circles').data and hidden_opaque.encode() not in guest.get('/circles').data,'Anonymous discovery lists only Public Circles')
change('UPDATE circles SET pinned_post_id=? WHERE id=?',(private_pid,pc))
check(b'PRIVATE CIRCLE SENTINEL' not in guest.get('/circles/'+pt).data,'Private pin never exposes content')
change('UPDATE circles SET public_read=0 WHERE id=?',(pc,))
check(guest.get('/circles/'+pt).status_code==404 and guest.get(url).status_code==404,'Turning off public Circle immediately closes originals')
check(get('Outsider','/circles/'+pt).status_code==200 and b'PUBLIC CIRCLE SENTINEL' not in get('Outsider','/circles/'+pt).data,'Discoverable mode shows no posts to outsiders')
change('UPDATE circles SET public_read=1 WHERE id=?',(pc,))
change("UPDATE circle_post_visibility SET audience='private' WHERE post_id=?",(pid,))
check(guest.get(url).status_code==404,'Author revocation makes original private immediately')
change("UPDATE circle_post_visibility SET audience='public' WHERE post_id=?",(pid,))
change('UPDATE circles SET archived=1 WHERE id=?',(pc,))
check(guest.get(url).status_code==404 and guest.get('/circles/'+pt).status_code==404,'Archive closes public Circle and posts')
change('UPDATE circles SET archived=0 WHERE id=?',(pc,))
change('INSERT INTO moderated_posts(post_id,author_id,hidden_by,reason) VALUES (?,?,?,?)',(pid,users['Owner'],users['Moderator'],'Public fixture'))
check(guest.get(url).status_code==404,'Site removal blocks public post')
change('DELETE FROM moderated_posts WHERE post_id=?',(pid,))
check(get('Teen',url).status_code==404,'Public Circle preserves age-band restrictions')
# Exercise real author edit form; old private content is never available through history.
change('DELETE FROM rate_buckets')
check(post('Owner','/edit_post/'+public,content='EDITED PUBLIC SENTINEL',vibes='',circle='',circle_audience='private').status_code==302,'Author can switch own post to private')
check(guest.get(url).status_code==404,'Edit choice immediately applied')
check(post('Owner','/edit_post/'+public,content='EDITED PUBLIC SENTINEL',vibes='',circle='',circle_audience='public').status_code==302,'Author can publish own post explicitly')
check(guest.get(url).status_code==200,'Explicit author publication applied')
check(get('Outsider','/edit_post/'+public).status_code!=200,'Non-author cannot edit public post')
# Real upload permissions, search and transitions are exercised end-to-end.
change('DELETE FROM rate_buckets')
image=io.BytesIO();Image.new('RGB',(8,8),'green').save(image,'PNG');image.seek(0)
upload=clients['Owner'].post('/create_post', data={'theme_csrf_token':token,'circle_id':pt,'circle_audience':'public','content':'PUBLIC PHOTO SENTINEL','post_image':(image,'public.png')})
check(upload.status_code==302,'Public Circle image upload')
image_pid=query('SELECT MAX(post_id) FROM circle_posts WHERE circle_id=?',(pc,))[0][0]
filename=query('SELECT filename FROM post_media WHERE post_id=?',(image_pid,))[0][0]
media_url='/media-file/'+filename
media_response=guest.get(media_url);media_status=media_response.status_code;media_type=media_response.mimetype;media_bytes=media_response.data;media_response.close();check(media_status==200 and media_type=='image/webp' and Image.open(io.BytesIO(media_bytes)).size==(8,8),'Anonymous public attachment access')
check(b'PUBLIC PHOTO SENTINEL' in guest.get('/circles/'+pt).data,'Public gallery feed contains public image post')
change("UPDATE circle_post_visibility SET audience='private' WHERE post_id=?",(image_pid,))
r=guest.get(media_url);check(r.status_code==404,'Author making photo private revokes raw media');r.close()
# Owner setting route preserves all private post flags.
check(manage('Owner',pc,'settings',name='Fixture Public Circle',description='Public fixture',mode='discoverable').status_code==302,'Owner disables public viewing through settings')
check(guest.get('/circles/'+pt).status_code==404,'Owner setting revocation applied')
check(manage('Owner',pc,'settings',name='Fixture Public Circle',description='Public fixture',mode='public').status_code==302,'Owner enables public viewing through settings')
check(guest.get('/circles/'+pt).status_code==200 and guest.get('/posts/'+private_public).status_code==404,'Enabling Circle never publishes existing private post')
check(manage('Owner',hidden,'settings',name='Hidden fixture',mode='public').status_code==400,'Hidden mode cannot silently become public')
