check(guest.get(url).status_code==404,'Circle removal blocks public original')
change("DELETE FROM circle_content_removals WHERE circle_id=? AND target_id=?",(pc,pid))
change("UPDATE users SET verified=0 WHERE id=?",(users['Owner'],))
check(guest.get(url).status_code==404 and guest.get('/circles/'+pt).status_code==404,'Unavailable Circle owner hides public content')
change("UPDATE users SET verified=1 WHERE id=?",(users['Owner'],))
# Exercise the real rendered browser action, without numeric test aliases.
edit_url='/edit_post/'+private_public
edit_html=clients['Owner'].get(edit_url).get_data(as_text=True)
action=re.search(r'<form method="POST" action="([^"]+)"',edit_html).group(1)
check(action.endswith(edit_url),'Rendered update form uses public post ID')
delete_action=re.search(r'<form method="POST" action="([^"]*delete_post[^"]+)"',edit_html).group(1)
check(delete_action.endswith('/delete_post/'+private_public),'Rendered delete form uses public post ID')
response=clients['Owner'].post(action,data={'vibes':'','circle':'','content':'BROWSER FORM PUBLIC SENTINEL','circle_audience':'public','allow_circle_sharing':'1','theme_csrf_token':token})
check(response.status_code==302,'Rendered form saves sharing and public visibility')
check(guest.get('/posts/'+private_public).status_code==200 and b'BROWSER FORM PUBLIC SENTINEL' in guest.get('/circles/'+pt).data,'Saved public choice is visible to nonmembers')
response=clients['Owner'].post(action,data={'vibes':'','circle':'','content':'BROWSER FORM PRIVATE SENTINEL','circle_audience':'private','theme_csrf_token':token})
check(response.status_code==302 and guest.get('/posts/'+private_public).status_code==404,'Rendered form revokes public access')
check(b'BROWSER FORM PRIVATE SENTINEL' not in guest.get('/circles/'+pt).data,'Revoked post disappears from visitor feed')
check(clients['Outsider'].post(action,data={'vibes':'','circle':'','content':'FORGED EDIT','circle_audience':'public','theme_csrf_token':token}).status_code in (302,403,404),'Public ID form retains author authorization')
check(clients['Owner'].post(delete_action,data={'theme_csrf_token':token}).status_code==302 and not query('SELECT id FROM posts WHERE id=?',(private_pid,)),'Rendered delete action works only on disposable fixture')
